import {beginJsonDraft} from './core/json-draft.mjs';
export function move(base, args) {
  const transaction = beginJsonDraft(base);
  const draft = transaction.draft;
  try {
    const ids = draft.columns[args.column].ids;
    if (!(args.index in ids)) throw new RangeError("Choose an existing issue");
    const [id] = ids.splice(args.index, 1);
    draft.columns[args.target].ids.splice(0, 0, id);
    return transaction.finish();
  } finally { transaction.abort(); }
}

